    run=Path(run);ids=load(ROOT/'config/private_data_manifest.json')['sample_order'];plans=[load(run/f'plans/{sid}.json') if (run/f'plans/{sid}.json').exists() else {'status':'NOT_RUN'} for sid in ids]
